import type React from "react";
import { Composition } from "remotion";
import { Main169 } from "./Main169";
import type { MainProps } from "./Main169";
import { Shorts916 } from "./Shorts916";
import type { ShortsProps } from "./Shorts916";
// Example props so Studio runs out of the box. Real props are generated by the
// pipeline (pipeline/props.py → props/main169.json, pipeline/shorts.py → props/<id>.json).
import mainExample from "../props/main169.example.json";
import shortExample from "../props/short.example.json";

const defaultMainProps = mainExample as unknown as MainProps;
const defaultShortProps = shortExample as unknown as ShortsProps;

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="Main169"
        component={Main169}
        durationInFrames={defaultMainProps.totalDurationInFrames}
        fps={30}
        width={1920}
        height={1080}
        defaultProps={defaultMainProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: props.totalDurationInFrames,
        })}
      />
      <Composition
        id="Short-Example"
        component={Shorts916}
        durationInFrames={defaultShortProps.totalDurationInFrames}
        fps={30}
        width={1080}
        height={1920}
        defaultProps={defaultShortProps}
        calculateMetadata={({ props }) => ({
          durationInFrames: props.totalDurationInFrames,
        })}
      />
    </>
  );
};
